package com.ruoyi.paicli.service;

import com.ruoyi.common.constant.CacheConstants;
import com.ruoyi.common.core.domain.model.LoginUser;
import com.ruoyi.common.core.redis.RedisCache;
import com.ruoyi.paicli.configuration.PcTerminalProperties;
import com.ruoyi.paicli.domain.*;
import com.ruoyi.system.service.ISysUserService;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.socket.*;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/** 只托管授权、元数据和有界VT流；所有业务执行仍走既有中心服务及Runner任务循环。 */
@Service
@ConditionalOnProperty(prefix="paicli",name="enabled",havingValue="true")
public class PcTerminalService {
    private static final Set<String> ACTIVE=Set.of("STARTING","RUNNING","STOPPING");
    // Redis 3也支持Lua；使用模板现有值序列化器返回原值，GET与DEL必须在单次原子脚本内。
    static final DefaultRedisScript<String> CONSUME_TICKET_SCRIPT=new DefaultRedisScript<>(
        "local value = redis.call('GET', KEYS[1]); if value then redis.call('DEL', KEYS[1]); end; return value",String.class);
    private final PcStore store; private final PcAccess access; private final PcDeviceService devices;
    private final PcCrypto crypto; private final RedisCache redis; private final ISysUserService users;
    private final PcCommandService commands;
    private final PcToolService tools;
    private final PcKnowledgeService knowledge;
    private final PcTerminalOutbound outbound;
    private final PcTerminalProperties properties; private final TransactionTemplate transaction,persistTransaction;
    private final Map<Long,Host> hosts=new ConcurrentHashMap<>();
    private final Map<Long,Instant> hostSeen=new ConcurrentHashMap<>();
    private final Map<Long,Terminal> terminals=new ConcurrentHashMap<>();
    private record Host(WebSocketSession socket,String token,String bootId){}
    public record BrowserIdentity(long terminalId,String loginRef,String clientId){}
    public record CapabilityIdentity(long terminalId,LoginUser user){}
    private static final class Browser {
        final WebSocketSession socket; final BrowserIdentity identity;
        long acknowledged,sent,replayEnd; boolean hello,replaying;
        Browser(WebSocketSession s,BrowserIdentity i){socket=s;identity=i;}
    }
    private static final class Terminal {
        final long id,runner,session,workspace,owner; final String nonce,loginRef;
        final List<Map<String,Object>> output=new ArrayList<>();
        final Map<String,Browser> browsers=new LinkedHashMap<>();
        final Map<String,Map<String,Object>> attachments=new LinkedHashMap<>();
        final Map<String,Map<String,Object>> authorizations=new LinkedHashMap<>();
        final Set<Long> associatedTasks=ConcurrentHashMap.newKeySet();
        final Set<Long> generatedTasks=ConcurrentHashMap.newKeySet();
        final List<Map<String,Object>> exports=new ArrayList<>();
        boolean inputUncertain;
        int reservedTasks;
        volatile String state; String writer,capabilityHash,previousCapabilityHash,reason="";
        Instant expires,previousExpires,created,lastActivity,lastAttached,stoppedAt;
        long hostEpoch=1,writerEpoch=0,outputSeq,inputSeq,outputBytes; int cols,rows; String renderer;
        Terminal(PcRecord r,Map<String,Object> p){id=r.getId();runner=r.getRunnerId();session=r.getSessionId();workspace=r.getDirectoryContextId();owner=r.getOwnerId();state=r.getState();nonce=PcJson.text(p,"startNonce");loginRef=PcJson.text(p,"loginRef");renderer=PcJson.text(p,"renderer");cols=(int)number(p,"cols",100);rows=(int)number(p,"rows",30);hostEpoch=number(p,"hostEpoch",1);writerEpoch=number(p,"writerEpoch",0);created=r.getCreatedAt();lastActivity=created;lastAttached=created;}
    }
    public PcTerminalService(PcStore s,PcAccess a,PcDeviceService d,PcCrypto c,RedisCache r,ISysUserService u,PcCommandService cmd,PcToolService tool,PcKnowledgeService k,PcTerminalOutbound output,PcTerminalProperties p,@Qualifier("paicliTransactionManager") PlatformTransactionManager manager){store=s;access=a;devices=d;crypto=c;redis=r;users=u;commands=cmd;tools=tool;knowledge=k;outbound=output;properties=p;transaction=new TransactionTemplate(manager);persistTransaction=new TransactionTemplate(manager);persistTransaction.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_REQUIRES_NEW);}
    public Map<String,Object> readiness(long id){if(!properties.isEnabled())return Map.of("ready",false,"code","PC_TERMINAL_DISABLED","message","网页终端尚未启用，请管理员完成终端部署");if(!hasReadyHost(id))return Map.of("ready",false,"code","PC_TERMINAL_HOST_OFFLINE","message","编码宿主已登记，但真实PTY托管连接尚未在线");return Map.of("ready",true,"code","READY","message","终端托管连接已在线");}
    public boolean hasReadyHost(long id){return properties.isEnabled()&&hosts.containsKey(id)&&hosts.get(id).socket.isOpen()&&hostSeen.get(id)!=null&&hostSeen.get(id).plusSeconds(60).isAfter(store.clock.instant());}
    private void enabled(){if(!properties.isEnabled())throw new PcException(409,"PC_TERMINAL_DISABLED","网页终端尚未启用");}
    public boolean originAllowed(String origin){return origin!=null&&properties.getAllowedOrigins().contains(origin);}
    public LoginUser login(String ref){
        if(ref==null||ref.isBlank())throw PcException.deny("登录引用缺失");
        LoginUser login=redis.getCacheObject(CacheConstants.LOGIN_TOKEN_KEY+ref);
        if(login==null||login.getUserId()==null||login.getUser()==null||login.getExpireTime()==null||login.getExpireTime()<System.currentTimeMillis())throw new PcException(401,"PC_TERMINAL_LOGIN_REVOKED","原若依登录已撤销或过期");
        var account=users.selectUserById(login.getUserId());
        if(account==null||!"0".equals(account.getStatus())||!"0".equals(account.getDelFlag()))throw PcException.deny("若依账号已停用");
        return login;
    }
    public static void permission(LoginUser user,String value){if(!user.getUser().isAdmin()&&(user.getPermissions()==null||!user.getPermissions().contains("*:*:*")&&!user.getPermissions().contains(value)))throw PcException.deny("没有所需权限："+value);}
    private void authorize(Terminal t,String loginRef,boolean write){LoginUser user=login(loginRef);if(user.getUserId()!=t.owner)throw PcException.deny("仅终端owner可连接");permission(user,write?"paicli:terminal:use":"paicli:terminal:read");access.resource(PcTable.SESSION,t.session,t.owner,true,false);access.resource(PcTable.TERMINAL_SESSION,t.id,t.owner,true,false);PcRecord runner=store.require(PcTable.RUNNER,t.runner,false);if("REVOKED".equals(runner.getState()))throw PcException.deny("终端设备已撤销");}
    public synchronized Map<String,Object> create(LoginUser current,Map<String,Object> input){
        PcPersonalService.rejectLegacy(input);enabled();LoginUser user=login(current.getToken());permission(user,"paicli:terminal:use");permission(user,"paicli:session:read");
        trimCompleted();
        long session=PcJson.number(input,"sessionId");String renderer=Objects.toString(input.get("renderer"),"inline");if(!Set.of("inline","lanterna","plain").contains(renderer))throw PcException.invalid("终端界面须为inline、lanterna或plain");
        int cols=dimension(input,"cols",100,20,400),rows=dimension(input,"rows",30,5,120);
        return transaction.execute(status->{
            PcRecord sessionRow=access.resource(PcTable.SESSION,session,user.getUserId(),true,true);
            if(!Set.of("ACTIVE","DRAFT").contains(sessionRow.getState()))throw PcException.conflict("历史会话不能启动终端");if(sessionRow.getDirectoryContextId()==null)throw new PcException(409,"PC_DIRECTORY_NOT_READY","个人文件目录尚未准备，文字问答仍可使用");if(store.data(sessionRow).get("directoryPreparationTaskId")!=null&&!Boolean.TRUE.equals(store.data(sessionRow).get("directoryPrepared")))throw new PcException(409,"PC_DIRECTORY_PREPARING","本对话目录正在准备，完成后即可打开终端");
            PcRecord existing=store.mapper.findKey(PcTable.TERMINAL_SESSION,"active-session:"+session,false);if(existing!=null&&ACTIVE.contains(existing.getState())){Terminal t=terminals.get(existing.getId());if(t==null)throw PcException.conflict("旧终端托管已丢失，请结束旧实例后重新打开");authorize(t,user.getToken(),true);return view(t);}
            if(terminals.values().stream().filter(t->ACTIVE.contains(t.state)).count()>=properties.getGlobalLimit())throw limit("全局活跃终端已达到"+properties.getGlobalLimit()+"个，请先结束已有终端");
            PcRecord runner=store.require(PcTable.RUNNER,sessionRow.getRunnerId(),true);
            Host host=hosts.get(runner.getId());if(!"ONLINE".equals(runner.getState())||host==null||!host.socket.isOpen())throw PcException.conflict("Runner终端托管未在线");
            PcRunnerPrincipal principal=devices.authenticate(host.token);if(!principal.kind().equals("SESSION")||principal.ownerId()!=user.getUserId())throw PcException.deny("Runner不属于当前用户及目录");
            Object caps=store.data(runner).get("capabilities");if(!(caps instanceof List<?> list)||!list.contains("terminal"))throw PcException.conflict("Runner未声明真实PTY终端能力");
            // 用户及设备owner一致，仅统计当前owner，避免全局读取其他用户终端元数据。
            List<PcRecord> active=new ArrayList<>();for(String state:ACTIVE)active.addAll(store.mapper.list(PcTable.TERMINAL_SESSION,null,user.getUserId(),null,state));
            if(active.stream().filter(r->Objects.equals(r.getOwnerId(),user.getUserId())).count()>=properties.getUserLimit()||active.stream().filter(r->Objects.equals(r.getRunnerId(),runner.getId())).count()>=properties.getRunnerLimit())throw PcException.conflict("终端实例已达到用户或Runner额度");
            Map<String,Object> data=new LinkedHashMap<>();data.put("startNonce",UUID.randomUUID().toString());data.put("loginRef",user.getToken());data.put("renderer",renderer);data.put("cols",cols);data.put("rows",rows);data.put("hostEpoch",1L);data.put("writerEpoch",0L);
            PcRecord record=store.insert(PcTable.TERMINAL_SESSION,sessionRow.getDirectoryContextId(),user.getUserId(),null,session,runner.getId(),"TERMINAL","STARTING","active-session:"+session,data);
            Terminal t=new Terminal(record,data);terminals.put(t.id,t);
            Map<String,Object> start=frame(t,"START");start.put("ownerId",String.valueOf(t.owner));start.put("ownerUserId",String.valueOf(t.owner));PcRecord frozenDirectory=access.directory(t.workspace,t.owner,false);start.put("directoryContext",store.view(frozenDirectory));start.put("rootFingerprint",store.data(frozenDirectory).get("rootFingerprint"));start.put("sessionId",String.valueOf(t.session));start.put("directoryContextId",String.valueOf(t.workspace));start.put("runnerId",String.valueOf(t.runner));start.put("startNonce",t.nonce);start.put("renderer",renderer);start.put("cols",cols);start.put("rows",rows);start.putAll(issueCapability(t));
            org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){@Override public void afterCommit(){try{send(host.socket,start);}catch(PcException failed){synchronized(t){t.state="FAILED";persist(t,Map.of("reason","START_DELIVERY_FAILED"));}}}@Override public void afterCompletion(int completion){if(completion!=STATUS_COMMITTED)terminals.remove(t.id);}});
            return view(t);
        });
    }
    public Map<String,Object> detail(long id,LoginUser user){enabled();Terminal t=terminals.get(id);if(t!=null){authorize(t,user.getToken(),false);synchronized(t){return view(t);}}PcRecord r=access.resource(PcTable.TERMINAL_SESSION,id,user.getUserId(),true,false);permission(login(user.getToken()),"paicli:terminal:read");Map<String,Object> v=store.view(r);v.remove("loginRef");v.remove("startNonce");v.put("terminalId",String.valueOf(r.getId()));v.putIfAbsent("hostEpoch",1L);v.putIfAbsent("writerEpoch",0L);v.putIfAbsent("inputSeq",0L);v.putIfAbsent("outputSeq",0L);v.putIfAbsent("renderer","inline");v.putIfAbsent("cols",100);v.putIfAbsent("rows",30);if(ACTIVE.contains(r.getState()))v.put("reason","中心进程托管已丢失，请先结束旧实例，再重新打开终端；原任务保留");v.put("hostAvailable",false);return v;}
    public Map<String,Object> ticket(long id,LoginUser user,Map<String,Object> input){
        enabled();Terminal t=require(id);String client=client(input);authorize(t,user.getToken(),false);
        synchronized(t){if(!ACTIVE.contains(t.state))throw PcException.conflict("终端已结束");if(t.writer==null){permission(login(user.getToken()),"paicli:terminal:use");t.writer=client;t.writerEpoch++;t.inputSeq=0;persist(t,Map.of());}
            String ticket=crypto.token("pct_");String key="paicli:terminal:ticket:"+PcJson.digest(ticket);Map<String,Object> data=Map.of("terminalId",id,"loginRef",user.getToken(),"clientId",client);redis.setCacheObject(key,store.json.write(data),30,java.util.concurrent.TimeUnit.SECONDS);
            return Map.of("ticket",ticket,"protocols",List.of("paicli-terminal","paicli-ticket."+ticket),"terminalId",String.valueOf(id),"hostEpoch",t.hostEpoch,"writerEpoch",t.writerEpoch,"clientId",client,"canWrite",client.equals(t.writer),"expiresAt",store.clock.instant().plusSeconds(30).toString());}
    }
    public BrowserIdentity consumeTicket(String ticket,String origin){enabled();if(!originAllowed(origin))throw PcException.deny("终端连接Origin未批准");if(ticket==null||!ticket.matches("pct_[A-Za-z0-9_-]{43}"))throw PcException.deny("终端票据无效");Object raw=redis.redisTemplate.execute(CONSUME_TICKET_SCRIPT,List.of("paicli:terminal:ticket:"+PcJson.digest(ticket)));if(!(raw instanceof String text))throw PcException.deny("终端票据已使用或过期");Map<String,Object> data=store.json.read(text);Terminal t=require(PcJson.number(data,"terminalId"));String ref=PcJson.text(data,"loginRef");authorize(t,ref,false);return new BrowserIdentity(t.id,ref,PcJson.text(data,"clientId"));}
    public Map<String,Object> claim(long id,LoginUser user,Map<String,Object> input){Terminal t=require(id);authorize(t,user.getToken(),true);String client=client(input);synchronized(t){if(!ACTIVE.contains(t.state))throw PcException.conflict("终端已结束");if(number(input,"expectedWriterEpoch",-1)!=t.writerEpoch)throw PcException.conflict("输入控制版本已变化，请刷新后再接管");if(!client.equals(t.writer)){t.writer=client;t.writerEpoch++;t.inputSeq=0;for(Map<String,Object> request:t.attachments.values())if(Set.of("PENDING","READY").contains(request.get("state")))request.put("state","CANCELLED");for(Map<String,Object> request:t.authorizations.values())if("PENDING".equals(request.get("status")))request.put("status","REJECTED");persist(t,Map.of());}broadcastState(t);return view(t);}}
    public Map<String,Object> stop(long id,LoginUser user,Map<String,Object> input){enabled();PcRecord row=access.resource(PcTable.TERMINAL_SESSION,id,user.getUserId(),true,false);permission(login(user.getToken()),"paicli:terminal:use");if(Boolean.TRUE.equals(input.get("cancelTask")))throw PcException.invalid("请通过既有任务取消接口单独确认取消，再结束终端");Terminal t=terminals.get(id);if(t==null){transaction.execute(s->{PcRecord r=store.require(PcTable.TERMINAL_SESSION,id,true);r.setState("LOST");r.setUniqueKey(null);Map<String,Object>d=store.data(r);d.put("reason","中心托管状态丢失");store.save(PcTable.TERMINAL_SESSION,r,d);return null;});return detail(id,user);}synchronized(t){authorize(t,user.getToken(),true);stopHost(t,"USER_STOP");return view(t);}}
    private Map<String,Object> issueCapability(Terminal t){if(!Set.of("STARTING","RUNNING").contains(t.state))throw PcException.deny("终端已停止委托");String token=crypto.token("pctc_");t.previousCapabilityHash=t.capabilityHash;t.previousExpires=t.expires;t.capabilityHash=PcJson.digest(token);t.expires=store.clock.instant().plusSeconds(90);return Map.of("capabilityToken",token,"capabilityExpiresAt",t.expires.toString());}
    public CapabilityIdentity capability(String token){enabled();if(token==null||!token.matches("pctc_[A-Za-z0-9_-]{43}"))throw PcException.deny("终端单会话能力无效");String hash=PcJson.digest(token);for(Terminal t:terminals.values())synchronized(t){if(Set.of("STARTING","RUNNING").contains(t.state)&&((hash.equals(t.capabilityHash)&&t.expires!=null&&t.expires.isAfter(store.clock.instant()))||(hash.equals(t.previousCapabilityHash)&&t.previousExpires!=null&&t.previousExpires.isAfter(store.clock.instant())))){authorize(t,t.loginRef,true);return new CapabilityIdentity(t.id,login(t.loginRef));}}throw PcException.deny("终端能力已失效或撤销");}
    public PcRecord boundSession(CapabilityIdentity identity){Terminal t=require(identity.terminalId());authorize(t,t.loginRef,true);return access.resource(PcTable.SESSION,t.session,identity.user().getUserId(),true,false);}
    public void runnerConnected(WebSocketSession socket,String token,PcRunnerPrincipal principal){enabled();if(!"SESSION".equals(principal.kind()))throw PcException.deny("终端托管需要Runner会话凭证");Host old=hosts.put(principal.runnerId(),new Host(socket,token,""));hostSeen.put(principal.runnerId(),store.clock.instant());socket.getAttributes().put("runnerId",principal.runnerId());socket.getAttributes().put("runnerToken",token);if(old!=null&&old.socket!=socket)close(old.socket);}
    public void runnerFrame(WebSocketSession socket,Map<String,Object> input){
        String token=Objects.toString(socket.getAttributes().get("runnerToken"),"");PcRunnerPrincipal principal=devices.authenticate(token);if(!"SESSION".equals(principal.kind()))throw PcException.deny("托管凭证用途错误");Host host=hosts.get(principal.runnerId());if(host==null||host.socket!=socket)throw PcException.deny("旧Runner托管连接已撤销");
        hostSeen.put(principal.runnerId(),store.clock.instant());String type=PcJson.text(input,"type");if(type.equals("PING")){send(socket,Map.of("type","PONG"));return;}if(type.equals("PONG"))return;
        if(type.equals("HOST_HELLO")){reconcileHost(socket,token,principal,input);return;}
        Terminal t=require(PcJson.number(input,"terminalId"));if(t.runner!=principal.runnerId()||t.owner!=principal.ownerId()||number(input,"hostEpoch",-1)!=t.hostEpoch)throw PcException.deny("终端Runner或进程版本不匹配");
        synchronized(t){if(!Set.of("EXIT","FAILED","FAILURE").contains(type))authorize(t,t.loginRef,true);t.lastActivity=store.clock.instant();switch(type){
            case "READY"->{if(!"STARTING".equals(t.state))return;if(!t.nonce.equals(PcJson.text(input,"startNonce")))throw PcException.deny("启动nonce不匹配");t.state="RUNNING";persist(t,Map.of("pid",number(input,"pid",0),"bootId",Objects.toString(input.get("bootId"),host.bootId),"ptyMode",Objects.toString(input.get("ptyMode"),"unknown")));broadcastState(t);}
            case "OUTPUT"->{String data=PcJson.text(input,"data");int bytes=data.getBytes(StandardCharsets.UTF_8).length;long end=number(input,"outputSeq",-1);if(bytes<1||bytes>65536||end<1)throw PcException.invalid("终端输出序列或块大小不符");if(end<=t.outputSeq){if(!data.equals(t.output.get((int)end-1).get("data")))throw PcException.conflict("恢复的终端输出与已确认内容不符");send(socket,Map.of("type","OUTPUT_ACK","terminalId",String.valueOf(t.id),"hostEpoch",t.hostEpoch,"outputSeq",end));return;}if(end!=t.outputSeq+1)throw PcException.invalid("终端输出序列断裂");if(t.output.size()>=65536||t.outputBytes+bytes>properties.getReplayBytes()){stopHost(t,"OUTPUT_LIMIT");return;}Map<String,Object> output=frame(t,"OUTPUT");output.put("outputSeq",end);output.put("data",data);output.put("bytes",bytes);t.output.add(output);t.outputSeq=end;t.outputBytes+=bytes;for(Browser b:List.copyOf(t.browsers.values()))pump(t,b);send(socket,Map.of("type","OUTPUT_ACK","terminalId",String.valueOf(t.id),"hostEpoch",t.hostEpoch,"outputSeq",end));}
            case "INPUT_ACK","INPUT_REJECTED"->{if(number(input,"writerEpoch",-1)!=t.writerEpoch)return;long seq=number(input,"inputSeq",-1);if(seq<1||seq>t.inputSeq)throw PcException.invalid("输入确认不在已转发序号范围");if(type.equals("INPUT_REJECTED")){t.inputUncertain=true;t.reason="输入写入未确认，请核对任务后结束并重新打开终端";}for(Browser b:List.copyOf(t.browsers.values()))if(b.identity.clientId.equals(t.writer))sendBrowser(t,b,input);if(t.inputUncertain)broadcastState(t);}
            case "EXIT","FAILED","FAILURE"->{if(!Set.of("FAILED","LOST").contains(t.state)){t.state=type.equals("EXIT")?"EXITED":"FAILED";t.reason=Objects.toString(input.get("reason"),"CLI_EXIT");}t.capabilityHash=null;t.previousCapabilityHash=null;persist(t,Map.of("exitCode",number(input,"exitCode",-1),"reason",t.reason));broadcastState(t);broadcast(t,input);}
            case "REPLAY_COMPLETE"->{}
            case "RENEW"->{if(!Set.of("STARTING","RUNNING").contains(t.state))return;Map<String,Object> renewal=frame(t,"CAPABILITY");renewal.putAll(issueCapability(t));send(socket,renewal);}
            default->throw PcException.invalid("Runner终端帧类型无效");
        }}
    }
    public void runnerClosed(WebSocketSession socket){outbound.closed(socket);Object id=socket.getAttributes().get("runnerId");if(id instanceof Long runner){Host host=hosts.get(runner);if(host!=null&&host.socket==socket)hosts.remove(runner,host);}}
    private void reconcileHost(WebSocketSession socket,String token,PcRunnerPrincipal principal,Map<String,Object> input){
        String boot=PcJson.text(input,"bootId");if(boot.isBlank()||boot.length()>128)throw PcException.invalid("Runner bootId无效");hosts.put(principal.runnerId(),new Host(socket,token,boot));Set<Long> reported=new HashSet<>();
        Object list=input.get("terminals");if(!(list instanceof List<?> values)||values.size()>8)throw PcException.invalid("托管实例列表非法");
        for(Object value:values){if(!(value instanceof Map<?,?> map))throw PcException.invalid("托管实例非法");long id=Long.parseLong(String.valueOf(map.get("terminalId")));Terminal t=terminals.get(id);
            if(t==null||t.runner!=principal.runnerId()||t.owner!=principal.ownerId()||!t.nonce.equals(map.get("startNonce"))||number(map,"hostEpoch",-1)!=t.hostEpoch){send(socket,Map.of("type","STOP","terminalId",String.valueOf(id),"hostEpoch",number(map,"hostEpoch",1),"reason","CENTER_INSTANCE_LOST"));continue;}
            reported.add(id);synchronized(t){if(!Set.of("STARTING","RUNNING").contains(t.state)){send(socket,Map.of("type","STOP","terminalId",String.valueOf(id),"hostEpoch",t.hostEpoch,"reason","CENTER_INSTANCE_ENDED"));continue;}authorize(t,t.loginRef,true);if("EXITED".equals(map.get("state"))||"EXIT".equals(map.get("state"))){t.state="EXITED";t.reason="CLI_EXIT_WHILE_DETACHED";t.capabilityHash=null;t.previousCapabilityHash=null;persist(t,Map.of("reason",t.reason));broadcastState(t);continue;}Map<String,Object> renew=frame(t,"CAPABILITY");renew.putAll(issueCapability(t));send(socket,renew);Map<String,Object> replay=frame(t,"REPLAY");replay.put("afterOutputSeq",t.outputSeq);send(socket,replay);}
        }
        for(Terminal t:terminals.values())if(t.runner==principal.runnerId()&&!reported.contains(t.id)&&!"STARTING".equals(t.state)&&ACTIVE.contains(t.state))synchronized(t){t.state="LOST";t.reason="RUNNER_PROCESS_LOST";t.capabilityHash=null;t.previousCapabilityHash=null;persist(t,Map.of("reason",t.reason));broadcastState(t);}
    }
    public void browserConnected(WebSocketSession socket,BrowserIdentity identity){Terminal t=require(identity.terminalId);authorize(t,identity.loginRef,false);synchronized(t){for(Browser old:List.copyOf(t.browsers.values()))if(old.identity.clientId.equals(identity.clientId)){t.browsers.remove(old.socket.getId());close(old.socket);}if(t.browsers.size()>=8)throw PcException.conflict("同一终端最多附着8个窗口");Browser browser=new Browser(socket,identity);t.browsers.put(socket.getId(),browser);t.lastAttached=store.clock.instant();socket.getAttributes().put("terminalId",t.id);sendState(t,browser);}}
    public void browserFrame(WebSocketSession socket,Map<String,Object> input){
        Terminal t=require(((Number)socket.getAttributes().get("terminalId")).longValue());synchronized(t){Browser b=t.browsers.get(socket.getId());if(b==null)throw PcException.deny("终端连接已分离");authorize(t,b.identity.loginRef,false);String type=PcJson.text(input,"type");if(type.equals("PING")){send(socket,Map.of("type","PONG"));return;}if(type.equals("PONG"))return;
            if(type.equals("HELLO")){long after=Boolean.TRUE.equals(input.get("reset"))?0:number(input,"afterOutputSeq",0);if(after<0||after>t.outputSeq)throw PcException.invalid("输出恢复游标不在块边界");b.acknowledged=after;b.sent=after;b.hello=true;b.replaying=true;b.replayEnd=t.outputSeq;Map<String,Object> start=frame(t,"REPLAY_START");start.put("afterOutputSeq",after);start.put("outputSeq",b.replayEnd);send(socket,start);pump(t,b);return;}
            if(type.equals("OUTPUT_ACK")){long seq=number(input,"outputSeq",-1);if(seq<b.acknowledged||seq>b.sent)throw PcException.invalid("输出ACK不在已发送范围");b.acknowledged=seq;pump(t,b);return;}
            if(!"RUNNING".equals(t.state)||!b.hello||b.replaying||t.inputUncertain)throw PcException.conflict("终端当前不可输入；若上次输入未确认，请核对任务后重新打开终端");authorize(t,b.identity.loginRef,true);if(!b.identity.clientId.equals(t.writer)||number(input,"writerEpoch",-1)!=t.writerEpoch||number(input,"hostEpoch",-1)!=t.hostEpoch)throw PcException.deny("本窗口没有当前输入控制权");t.lastActivity=store.clock.instant();
            if(type.equals("INPUT")){String data=PcJson.text(input,"data");boolean binary="base64".equals(input.get("encoding"));String dataBase64=PcJson.text(input,"dataBase64");int size;if(binary){if(dataBase64.length()>22000)throw PcException.invalid("二进制输入编码超限");try{size=Base64.getDecoder().decode(dataBase64).length;}catch(IllegalArgumentException invalid){throw PcException.invalid("二进制输入base64无效");}}else size=data.getBytes(StandardCharsets.UTF_8).length;long seq=number(input,"inputSeq",-1);if(size<1||size>16384||seq<1)throw PcException.invalid("输入块大小或序号非法");if(seq<=t.inputSeq)return;if(seq!=t.inputSeq+1)throw PcException.conflict("输入序号断裂，请核对未确认输入");Map<String,Object> frame=frame(t,"INPUT");frame.put("writerEpoch",t.writerEpoch);frame.put("inputSeq",seq);if(binary){frame.put("encoding","base64");frame.put("dataBase64",dataBase64);}else frame.put("data",data);sendHost(t,frame);t.inputSeq=seq;}
            else if(type.equals("RESIZE")){t.cols=dimension(input,"cols",t.cols,20,400);t.rows=dimension(input,"rows",t.rows,5,120);Map<String,Object> frame=frame(t,"RESIZE");frame.put("cols",t.cols);frame.put("rows",t.rows);sendHost(t,frame);}
            else throw PcException.invalid("浏览器终端帧类型无效");
        }}
    public void browserClosed(WebSocketSession socket){outbound.closed(socket);Object id=socket.getAttributes().get("terminalId");if(id instanceof Long terminal){Terminal t=terminals.get(terminal);if(t!=null)synchronized(t){t.browsers.remove(socket.getId());if(t.browsers.isEmpty())t.lastAttached=store.clock.instant();}}}
    private void pump(Terminal t,Browser b){if(!b.hello||!b.socket.isOpen())return;try{authorize(t,b.identity.loginRef,false);long unacknowledged=0;for(Map<String,Object> f:t.output)if(number(f,"outputSeq",0)>b.acknowledged&&number(f,"outputSeq",0)<=b.sent)unacknowledged+=number(f,"bytes",0);for(Map<String,Object> frame:t.output){long seq=number(frame,"outputSeq",0);if(seq<=b.sent)continue;if(unacknowledged>=256*1024)break;if(b.replaying&&seq>b.replayEnd)break;send(b.socket,frame);b.sent=seq;unacknowledged+=number(frame,"bytes",0);}if(b.replaying&&b.acknowledged>=b.replayEnd){b.replaying=false;Map<String,Object> end=frame(t,"REPLAY_END");end.put("outputSeq",b.replayEnd);send(b.socket,end);sendState(t,b);replayRequests(t,b);pump(t,b);}}catch(PcException disconnected){t.browsers.remove(b.socket.getId());close(b.socket);}}
    private void replayRequests(Terminal t,Browser b){if(!t.exports.isEmpty()){Map<String,Object> frame=frame(t,"EXPORT_READY");frame.put("sessionId",String.valueOf(t.session));frame.put("artifacts",List.copyOf(t.exports));sendBrowser(t,b,frame);}if(!b.identity.clientId.equals(t.writer))return;for(Map<String,Object> req:t.attachments.values())if("PENDING".equals(req.get("state"))){Map<String,Object> frame=frame(t,"ATTACHMENT_REQUEST");frame.putAll(req);frame.put("source","clipboard");sendBrowser(t,b,frame);}for(Map<String,Object> req:t.authorizations.values())if("PENDING".equals(req.get("status"))){Map<String,Object> frame=frame(t,"AUTHORIZATION_REQUEST");frame.putAll(publicAuthorization(req));sendBrowser(t,b,frame);}}
    public Map<String,Object> authorizationRequest(CapabilityIdentity identity){Terminal t=require(identity.terminalId);synchronized(t){bridgeCapacity(t);List<Map<String,Object>> targets=freezeSnapshotTargets(t.owner);ensureCapacity(t,(int)targets.stream().filter(x->"READY".equals(x.get("status"))).count());Map<String,Object> req=authorizationBase(t,"SNAPSHOT_CLEAN_ALL","snapshot","clean all");req.put("permission","paicli:snapshot:restore");req.put("reason","仅对本清单中当前用户有权访问的目录生成快照清理预览/任务；后续独立审批继续生效");req.put("frozenTargets",targets);return publishAuthorization(t,req);}}
    private Map<String,Object> authorizationBase(Terminal t,String operation,String command,String arguments){Map<String,Object> req=new LinkedHashMap<>();req.put("requestId",UUID.randomUUID().toString());req.put("operation",operation);req.put("command",command);req.put("arguments",arguments);req.put("status","PENDING");req.put("writerEpoch",t.writerEpoch);req.put("createdAt",store.clock.instant().toString());return req;}
    private Map<String,Object> publishAuthorization(Terminal t,Map<String,Object> req){t.authorizations.put(PcJson.text(req,"requestId"),req);for(Browser b:List.copyOf(t.browsers.values()))if(b.identity.clientId.equals(t.writer)){Map<String,Object> frame=frame(t,"AUTHORIZATION_REQUEST");frame.putAll(publicAuthorization(req));sendBrowser(t,b,frame);}return Map.of("authorizationRequestId",req.get("requestId"),"authorizationStatus","PENDING");}
    private List<Map<String,Object>> freezeSnapshotTargets(long owner){List<Map<String,Object>> targets=new ArrayList<>();for(PcRecord workspace:store.mapper.visibleWorkspaces(owner)){if(targets.size()>=128)throw limit("快照授权目标超过128个，请分目录处理");Map<String,Object> target=new LinkedHashMap<>();target.put("directoryContextId",String.valueOf(workspace.getId()));target.put("directoryVersion",workspace.getVersion());target.put("directoryName",Objects.toString(store.data(workspace).get("name"),String.valueOf(workspace.getId())));target.put("directoryState",workspace.getState());target.put("status","BLOCKED");if(!"VERIFIED".equals(workspace.getState()))target.put("reason","目录未启用");else{var runners=store.mapper.list(PcTable.RUNNER,null,owner,null,"ONLINE").stream().filter(r->Objects.equals(r.getId(),workspace.getRunnerId())).toList();if(runners.isEmpty())target.put("reason","暂无在线Runner");else{PcRecord runner=runners.get(0);target.put("runnerId",String.valueOf(runner.getId()));target.put("runnerConfigurationHash",runnerScopeHash(runner));target.put("rootFingerprint",store.data(workspace).get("rootFingerprint"));target.put("status","READY");}}targets.add(target);}return targets;}
    private String runnerScopeHash(PcRecord runner){Map<String,Object> current=store.data(runner);Map<String,Object> semantic=new LinkedHashMap<>();semantic.put("directoryContextId",runner.getDirectoryContextId());semantic.put("ownerId",runner.getOwnerId());for(String field:List.of("administrationVersion","rootFingerprint","sandboxVerified","sandboxAttestation","capabilities","platform"))semantic.put(field,current.get(field));return store.json.hash(semantic);}
    private Map<String,Object> executeFrozenSnapshot(Terminal t,Map<String,Object> req){return transaction.execute(status->{
        Object frozen=req.get("frozenTargets");if(!(frozen instanceof List<?> targets))throw PcException.invalid("快照授权目标缺失");List<Map<String,Object>> tasks=new ArrayList<>(),blocked=new ArrayList<>();
        // 固定目标而非重新枚举：授权后新增成员关系或目录绝不会进入此次执行。
        List<Map<String,Object>> ordered=new ArrayList<>();for(Object value:targets){@SuppressWarnings("unchecked")Map<String,Object> target=(Map<String,Object>)value;ordered.add(target);}ordered.sort(Comparator.comparingLong(x->PcJson.number(x,"directoryContextId")));
        for(Map<String,Object> target:ordered){long id=PcJson.number(target,"directoryContextId");PcRecord workspace=store.require(PcTable.DIRECTORY_CONTEXT,id,true);if(workspace.getVersion()!=PcJson.number(target,"directoryVersion")||!workspace.getState().equals(target.get("directoryState")))throw PcException.conflict("冻结的目录配置已变化，请重新授权");if(!"READY".equals(target.get("status"))){blocked.add(Map.of("directoryContextId",String.valueOf(id),"reason",Objects.toString(target.get("reason"),"前提未满足")));continue;}access.directory(id,t.owner,false);PcRecord runner=store.require(PcTable.RUNNER,PcJson.number(target,"runnerId"),true);if(!"ONLINE".equals(runner.getState())||!Objects.equals(runner.getId(),workspace.getRunnerId())||!Objects.equals(runner.getOwnerId(),t.owner)||!runnerScopeHash(runner).equals(target.get("runnerConfigurationHash")))throw PcException.conflict("冻结的Runner、仓库或安全配置已变化，请重新授权");}
        for(Map<String,Object> target:ordered)if("READY".equals(target.get("status")))tasks.add(knowledge.cleanCurrent(t.owner,PcJson.number(target,"directoryContextId"),PcJson.number(target,"runnerId"),null));
        return Map.of("successful",true,"message","冻结目标的清理预览/任务已登记","data",Map.of("status",blocked.isEmpty()?"QUEUED":tasks.isEmpty()?"BLOCKED":"PARTIAL","tasks",tasks,"blocked",blocked,"range","all","message","仅冻结清单；逐目录预览和独立审批继续生效"));
    });}
    public Map<String,Object> taskAuthorization(CapabilityIdentity identity,long taskId,boolean cancel){Terminal t=require(identity.terminalId);synchronized(t){bridgeCapacity(t);ensureCapacity(t,t.associatedTasks.contains(taskId)?0:1);PcRecord task=access.resource(PcTable.TASK,taskId,t.owner,true,false);if(!Objects.equals(task.getDirectoryContextId(),t.workspace))throw PcException.deny("网页任务授权只允许当前目录本人任务");Map<String,Object> req=authorizationBase(t,cancel?"TASK_CANCEL":"TASK_LOG","task",(cancel?"cancel ":"log ")+taskId);req.put("taskId",String.valueOf(taskId));req.put("taskSessionId",String.valueOf(task.getSessionId()));req.put("taskVersion",task.getVersion());req.put("permission",cancel?"paicli:task:cancel":"paicli:task:read");req.put("preview",Map.of("taskId",String.valueOf(taskId),"sessionId",String.valueOf(task.getSessionId()),"state",task.getState(),"title",Objects.toString(store.data(task).get("title"),"")));req.put("reason",cancel?"此任务不是当前会话；网页登录主体明确确认取消":"此任务不是当前会话；确认后仅授权读取这个任务的日志和产物");return publishAuthorization(t,req);}}
    public Map<String,Object> authorizationPoll(CapabilityIdentity identity,Map<String,Object> params,boolean cancel){Terminal t=require(identity.terminalId);synchronized(t){trimRequests(t);Map<String,Object> request=t.authorizations.get(PcJson.text(params,"requestId"));if(request==null)throw PcException.invalid("网页授权请求不存在");if(cancel&&"PENDING".equals(request.get("status")))request.put("status","REJECTED");Map<String,Object> result=publicAuthorization(request);if("EXECUTING".equals(result.get("status")))result.put("status","PENDING");return result;}}
    public Map<String,Object> authorizeOperation(long id,LoginUser user,Map<String,Object> input){
        Terminal t=require(id);authorize(t,user.getToken(),true);
        Map<String,Object> req;int reserved=0;
        synchronized(t){
            trimRequests(t);
            if(!client(input).equals(t.writer)||number(input,"writerEpoch",-1)!=t.writerEpoch)throw PcException.deny("只有当前输入窗口可决定网页授权");
            req=t.authorizations.get(PcJson.text(input,"requestId"));
            if(req!=null&&"REJECT".equals(PcJson.text(input,"decision"))&&"EXPIRED".equals(req.get("status")))return publicAuthorization(req);
            if(req==null||!"PENDING".equals(req.get("status"))||number(req,"writerEpoch",-1)!=t.writerEpoch)throw PcException.conflict("网页授权请求已失效");
            String decision=PcJson.text(input,"decision");
            if("REJECT".equals(decision)){req.put("status","REJECTED");return publicAuthorization(req);}
            if(!"APPROVE".equals(decision))throw PcException.invalid("授权决定须为APPROVE或REJECT");
            if("SNAPSHOT_CLEAN_ALL".equals(req.get("operation"))&&req.get("frozenTargets") instanceof List<?> targets)reserved=(int)targets.stream().filter(x->x instanceof Map<?,?> m&&"READY".equals(m.get("status"))).count();else if(Set.of("TASK_LOG","TASK_CANCEL").contains(req.get("operation"))&&!t.associatedTasks.contains(PcJson.number(req,"taskId")))reserved=1;ensureCapacity(t,reserved);t.reservedTasks+=reserved;req.put("status","EXECUTING");
        }
        try{
                Map<String,Object> result;
                if("SNAPSHOT_CLEAN_ALL".equals(req.get("operation"))){permission(login(user.getToken()),"paicli:snapshot:read");permission(login(user.getToken()),"paicli:snapshot:restore");result=executeFrozenSnapshot(t,req);synchronized(t){registerTasks(t,result,true,0);}}
                else if(Set.of("TASK_LOG","TASK_CANCEL").contains(req.get("operation"))){permission(login(user.getToken()),PcJson.text(req,"permission"));result=transaction.execute(status->{long taskId=PcJson.number(req,"taskId");PcRecord task=access.resource(PcTable.TASK,taskId,t.owner,true,true);if(!Objects.equals(task.getDirectoryContextId(),t.workspace)||task.getVersion()!=PcJson.number(req,"taskVersion")||!Objects.equals(String.valueOf(task.getSessionId()),req.get("taskSessionId")))throw PcException.conflict("任务归属或状态版本已变化，请重新授权");return commands.command(t.owner,t.session,"terminal-authorization:"+req.get("requestId"),"task",PcJson.text(req,"arguments"));});synchronized(t){t.associatedTasks.add(PcJson.number(req,"taskId"));}}
                else if("APPROVAL_DECISION".equals(req.get("operation"))){
                    permission(login(user.getToken()),"paicli:approval:decide");long approval=PcJson.number(req,"approvalId");PcRecord row=access.resource(PcTable.APPROVAL,approval,t.owner,false,false);if(row.getParentId()==null||!t.generatedTasks.contains(row.getParentId()))throw PcException.deny("审批不再属于本终端关联任务");access.approve(row.getDirectoryContextId(),t.owner);
                    Map<String,Object> saved=tools.decision(t.owner,approval,PcJson.number(req,"version"),"terminal-authorization:"+req.get("requestId"),PcJson.object(req,"frozenInput"));result=Map.of("successful",true,"message","中心审批决定已保存","data",saved);
                }else throw PcException.deny("未登记的网页授权用途");
                synchronized(t){req.put("result",result);req.put("status","APPROVED");return publicAuthorization(req);}
        }catch(PcException denied){synchronized(t){req.put("status","FAILED");req.put("reason",denied.getMessage());}throw denied;}catch(RuntimeException failure){synchronized(t){req.put("status","FAILED");req.put("reason","授权执行失败，请核对中心实际状态后重新发起");}throw failure;}finally{synchronized(t){t.reservedTasks-=reserved;}}
    }
    public void registerCommandTasks(CapabilityIdentity identity,Map<String,Object> result){Terminal t=require(identity.terminalId);Runnable register=()->{synchronized(t){registerTasks(t,result,false,0);}};if(org.springframework.transaction.support.TransactionSynchronizationManager.isSynchronizationActive())org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){@Override public void afterCommit(){register.run();}});else register.run();}
    private void registerTasks(Terminal t,Object result,boolean crossWorkspace,int depth){if(depth>12)return;if(result instanceof Map<?,?> map){Object candidate=map.get("taskId");if(candidate==null&&Set.of("TASK","CONTROL").contains(Objects.toString(map.get("kind"),"")))candidate=map.get("id");if(candidate!=null)try{PcRecord task=store.require(PcTable.TASK,Long.parseLong(String.valueOf(candidate)),false);if(Objects.equals(task.getOwnerId(),t.owner)&&(crossWorkspace||Objects.equals(task.getDirectoryContextId(),t.workspace))){access.directory(task.getDirectoryContextId(),t.owner,false);if(!Objects.equals(task.getSessionId(),t.session)){t.associatedTasks.add(task.getId());t.generatedTasks.add(task.getId());}}}catch(PcException ignored){}for(Object value:map.values())registerTasks(t,value,crossWorkspace,depth+1);}else if(result instanceof List<?> values)for(Object value:values)registerTasks(t,value,crossWorkspace,depth+1);}
    public boolean associatedTask(CapabilityIdentity identity,long id){Terminal t=require(identity.terminalId);synchronized(t){return t.associatedTasks.contains(id);}}
    public boolean generatedTask(CapabilityIdentity identity,long id){Terminal t=require(identity.terminalId);synchronized(t){return t.generatedTasks.contains(id);}}
    public void ensureTaskCapacity(CapabilityIdentity identity){Terminal t=require(identity.terminalId);synchronized(t){ensureCapacity(t,1);t.reservedTasks++;}if(org.springframework.transaction.support.TransactionSynchronizationManager.isSynchronizationActive())org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){@Override public void afterCompletion(int status){synchronized(t){t.reservedTasks--;}}});else synchronized(t){t.reservedTasks--;}}
    private void ensureCapacity(Terminal t,int additions){if(additions<0||t.associatedTasks.size()+t.reservedTasks+additions>128)throw limit("本终端关联任务已达到128个，请新开终端；已有任务和账本保留");}
    private static PcException limit(String message){return new PcException(429,"PC_TERMINAL_RESOURCE_LIMIT",message);}
    private void bridgeCapacity(Terminal t){trimRequests(t);if(t.authorizations.size()>=128)throw limit("网页授权请求达到128条保存上限，请等待已完成记录过期");if(t.authorizations.values().stream().anyMatch(r->Set.of("PENDING","EXECUTING").contains(r.get("status"))))throw PcException.conflict("已有待处理网页授权请求");}
    private void trimRequests(Terminal t){Instant now=store.clock.instant();trimRequestMap(t.attachments,"state",now);trimRequestMap(t.authorizations,"status",now);}
    private void trimRequestMap(Map<String,Map<String,Object>> requests,String field,Instant now){Iterator<Map.Entry<String,Map<String,Object>>> iterator=requests.entrySet().iterator();List<Map.Entry<String,Map<String,Object>>> completed=new ArrayList<>();while(iterator.hasNext()){Map.Entry<String,Map<String,Object>> entry=iterator.next();Map<String,Object> r=entry.getValue();Instant created=Instant.parse(PcJson.text(r,"createdAt"));String state=Objects.toString(r.get(field),"");if(Set.of("PENDING","READY").contains(state)&&created.plusSeconds(300).isBefore(now)){r.put(field,"EXPIRED");state="EXPIRED";}if(!Set.of("PENDING","READY","EXECUTING").contains(state)){if(created.plusSeconds(600).isBefore(now))iterator.remove();else completed.add(entry);}}completed.sort(Comparator.comparing(x->PcJson.text(x.getValue(),"createdAt")));while(completed.size()>64){Map.Entry<String,Map<String,Object>> oldest=completed.remove(0);requests.remove(oldest.getKey());}}
    private void trimCompleted(){List<Terminal> ended=terminals.values().stream().filter(t->!ACTIVE.contains(t.state)).sorted(Comparator.comparing((Terminal t)->t.lastActivity).reversed()).toList();Map<Long,Integer> owners=new HashMap<>();int retained=0;for(Terminal t:ended){int count=owners.getOrDefault(t.owner,0);if(count>=8||retained>=32){synchronized(t){if(!ACTIVE.contains(t.state)&&terminals.remove(t.id,t)){for(Browser b:List.copyOf(t.browsers.values()))close(b.socket);t.browsers.clear();t.output.clear();t.outputBytes=0;}}}else{owners.put(t.owner,count+1);retained++;}}}
    public Map<String,Object> approvalAuthorization(CapabilityIdentity identity,long approval,String decision,Map<String,Object> input){Terminal t=require(identity.terminalId);synchronized(t){bridgeCapacity(t);PcRecord row=access.resource(PcTable.APPROVAL,approval,t.owner,false,false);access.approve(row.getDirectoryContextId(),t.owner);if(row.getParentId()==null||!t.generatedTasks.contains(row.getParentId()))throw PcException.deny("审批必须属于本终端创建的关联任务");if(!Set.of("APPROVE","REJECT","SKIP","REVISE").contains(decision))throw PcException.invalid("审批决定无效");String id=UUID.randomUUID().toString();Map<String,Object> req=new LinkedHashMap<>();req.put("requestId",id);req.put("operation","APPROVAL_DECISION");req.put("command","approval");req.put("arguments","decide "+approval+" "+decision);req.put("approvalId",String.valueOf(approval));req.put("version",row.getVersion());req.put("directoryContextId",String.valueOf(row.getDirectoryContextId()));req.put("preview",tools.approvalView(row));req.put("reason","关联任务在另一目录；网页登录主体确认后执行原审批规则");req.put("status","PENDING");req.put("writerEpoch",t.writerEpoch);req.put("createdAt",store.clock.instant().toString());Map<String,Object> frozen=new LinkedHashMap<>(input);frozen.put("decision",decision);frozen.put("inputHash",store.data(row).get("argsHash"));frozen.putIfAbsent("feedback","");req.put("frozenInput",frozen);t.authorizations.put(id,req);for(Browser b:List.copyOf(t.browsers.values()))if(b.identity.clientId.equals(t.writer)){Map<String,Object> frame=frame(t,"AUTHORIZATION_REQUEST");frame.putAll(publicAuthorization(req));sendBrowser(t,b,frame);}return Map.of("authorizationRequestId",id,"authorizationStatus","PENDING");}}
    public Map<String,Object> associatedApproval(CapabilityIdentity identity,long approval){Terminal t=require(identity.terminalId);synchronized(t){PcRecord row=access.resource(PcTable.APPROVAL,approval,t.owner,false,false);if(row.getParentId()==null||!t.generatedTasks.contains(row.getParentId()))throw PcException.deny("审批不属于本终端关联任务");access.approve(row.getDirectoryContextId(),t.owner);return tools.approvalView(row);}}
    private Map<String,Object> publicAuthorization(Map<String,Object> req){Map<String,Object> view=new LinkedHashMap<>(req);view.remove("frozenInput");if(req.get("frozenInput") instanceof Map<?,?> frozen)for(String field:List.of("decision","feedback","revisedArguments","inputHash"))if(frozen.get(field)!=null)view.put(field,frozen.get(field));return view;}
    public void exportReady(CapabilityIdentity identity,List<Map<String,Object>> artifacts){Terminal t=require(identity.terminalId);Runnable deliver=()->{synchronized(t){t.exports.addAll(artifacts);while(t.exports.size()>64)t.exports.remove(0);Map<String,Object> frame=frame(t,"EXPORT_READY");frame.put("sessionId",String.valueOf(t.session));frame.put("artifacts",artifacts);broadcast(t,frame);}};if(org.springframework.transaction.support.TransactionSynchronizationManager.isSynchronizationActive())org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){@Override public void afterCommit(){deliver.run();}});else deliver.run();}
    public Map<String,Object> attachmentRequest(CapabilityIdentity identity,Map<String,Object> params){Terminal t=require(identity.terminalId);synchronized(t){trimRequests(t);if(t.attachments.size()>=128)throw limit("终端附件请求达到128条保存上限，请等待已完成记录过期");if(t.writer==null)throw PcException.conflict("没有网页输入控制者");if(t.attachments.values().stream().anyMatch(v->"PENDING".equals(v.get("state"))))throw PcException.conflict("已有待处理图片请求");String id=UUID.randomUUID().toString();Map<String,Object> req=new LinkedHashMap<>();req.put("requestId",id);req.put("state","PENDING");req.put("writerEpoch",t.writerEpoch);req.put("createdAt",store.clock.instant().toString());t.attachments.put(id,req);Map<String,Object> frame=frame(t,"ATTACHMENT_REQUEST");frame.putAll(req);frame.put("source",Objects.toString(params.get("source"),"clipboard"));for(Browser b:List.copyOf(t.browsers.values()))if(b.identity.clientId.equals(t.writer))sendBrowser(t,b,frame);return new LinkedHashMap<>(req);}}
    public Map<String,Object> attachmentPoll(CapabilityIdentity identity,Map<String,Object> params){Terminal t=require(identity.terminalId);synchronized(t){trimRequests(t);Map<String,Object> req=t.attachments.get(PcJson.text(params,"requestId"));if(req==null)throw PcException.invalid("图片请求不存在");if(Boolean.TRUE.equals(params.get("cancel")))req.put("state","CANCELLED");return new LinkedHashMap<>(req);}}
    public Map<String,Object> attachmentCancel(CapabilityIdentity identity,Map<String,Object> params){Map<String,Object> cancelled=new LinkedHashMap<>(params);cancelled.put("cancel",true);return attachmentPoll(identity,cancelled);}
    public Map<String,Object> attachments(long id,LoginUser user,Map<String,Object> input){Terminal t=require(id);authorize(t,user.getToken(),true);synchronized(t){trimRequests(t);if(!client(input).equals(t.writer)||number(input,"writerEpoch",-1)!=t.writerEpoch)throw PcException.deny("图片只能由当前输入窗口提交");Map<String,Object> req=t.attachments.get(PcJson.text(input,"requestId"));if(req!=null&&"EXPIRED".equals(req.get("state"))&&"CANCELLED".equals(input.get("state")))return new LinkedHashMap<>(req);if(req==null||!"PENDING".equals(req.get("state"))||number(req,"writerEpoch",-1)!=t.writerEpoch)throw PcException.conflict("图片请求已失效");String state=Objects.toString(input.get("state"),"READY");if(Set.of("FAILED","CANCELLED").contains(state)){req.put("state",state);return new LinkedHashMap<>(req);}Object raw=input.get("artifactIds");if(!(raw instanceof List<?> ids)||ids.isEmpty()||ids.size()>8)throw PcException.invalid("每次网页图片请求须有1–8张图片");List<String> accepted=new ArrayList<>();for(Object value:ids){long artifact=Long.parseLong(String.valueOf(value));PcRecord r=access.resource(PcTable.ARTIFACT,artifact,t.owner,true,false);if(!"TURN_IMAGE".equals(r.getKind())||!Objects.equals(r.getDirectoryContextId(),t.workspace)||r.getSessionId()!=null&&!Objects.equals(r.getSessionId(),t.session))throw PcException.deny("图片不属于终端当前用户和会话");accepted.add(String.valueOf(artifact));}req.put("artifactIds",accepted);req.put("state","READY");return new LinkedHashMap<>(req);}}
    public boolean attachmentAllowed(CapabilityIdentity identity,long artifact){Terminal t=require(identity.terminalId);synchronized(t){return t.attachments.values().stream().filter(v->"READY".equals(v.get("state"))).anyMatch(v->v.get("artifactIds") instanceof List<?> ids&&ids.contains(String.valueOf(artifact)));}}
    public void consumeAttachments(CapabilityIdentity identity,List<Long> ids){Terminal t=require(identity.terminalId);Runnable consume=()->{synchronized(t){for(Map<String,Object> req:t.attachments.values())if("READY".equals(req.get("state"))&&req.get("artifactIds") instanceof List<?> accepted&&accepted.stream().allMatch(id->ids.contains(Long.parseLong(String.valueOf(id)))))req.put("state","CONSUMED");}};if(org.springframework.transaction.support.TransactionSynchronizationManager.isSynchronizationActive())org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){@Override public void afterCommit(){consume.run();}});else consume.run();}
    @Scheduled(fixedDelay=15000)
    public void expire(){
        if(!properties.isEnabled())return;Instant now=store.clock.instant();trimCompleted();
        for(Terminal t:terminals.values())synchronized(t){try{
            trimRequests(t);
            if(!ACTIVE.contains(t.state)){if(t.lastActivity.plusSeconds(600).isBefore(now)&&t.browsers.isEmpty())terminals.remove(t.id);continue;}
            if("STOPPING".equals(t.state)){if(t.stoppedAt!=null&&t.stoppedAt.plusSeconds(20).isBefore(now)){t.state="LOST";t.reason="STOP_NOT_CONFIRMED";persist(t,Map.of("reason",t.reason));broadcastState(t);}continue;}
            authorize(t,t.loginRef,true);Host h=hosts.get(t.runner);if(h!=null)devices.authenticate(h.token);
            Instant seen=hostSeen.getOrDefault(t.runner,t.created);
            if((h==null||!h.socket.isOpen()||seen.plusSeconds(45).isBefore(now))&&seen.plusSeconds(45).isBefore(now)){if(h!=null){hosts.remove(t.runner,h);close(h.socket);}t.state="LOST";t.reason="RUNNER_LOST";t.capabilityHash=null;t.previousCapabilityHash=null;persist(t,Map.of("reason",t.reason));broadcastState(t);}
            else if("STARTING".equals(t.state)&&t.created.plusSeconds(20).isBefore(now))stopHost(t,"START_TIMEOUT");
            else if(t.created.plusSeconds(8*3600).isBefore(now)||t.lastActivity.plusSeconds(7200).isBefore(now)||t.browsers.isEmpty()&&t.lastAttached.plusSeconds(600).isBefore(now))stopHost(t,"TERMINAL_EXPIRED");
            else if(h!=null)send(h.socket,Map.of("type","PING"));
        }catch(Exception denied){try{stopHost(t,"AUTH_REVOKED");}catch(Exception persistenceFailure){t.reason="STOP_NOT_CONFIRMED";}for(Browser b:List.copyOf(t.browsers.values()))close(b.socket);}}
    }
    private void stopHost(Terminal t,String reason){if(!ACTIVE.contains(t.state)||"STOPPING".equals(t.state))return;t.state="STOPPING";t.reason=reason;t.stoppedAt=store.clock.instant();t.capabilityHash=null;t.previousCapabilityHash=null;for(Map<String,Object> req:t.attachments.values())if("PENDING".equals(req.get("state")))req.put("state","CANCELLED");for(Map<String,Object> req:t.authorizations.values())if("PENDING".equals(req.get("status")))req.put("status","REJECTED");persist(t,Map.of("reason",reason));Host h=hosts.get(t.runner);if(h!=null&&h.socket.isOpen()){Map<String,Object> stop=frame(t,"STOP");stop.put("reason",reason);try{send(h.socket,stop);}catch(PcException disconnected){t.state="LOST";persist(t,Map.of("reason",reason));}}else{t.state="LOST";persist(t,Map.of("reason",reason));}broadcastState(t);}
    private void persist(Terminal t,Map<String,Object> changes){persistTransaction.execute(status->{PcRecord r=store.require(PcTable.TERMINAL_SESSION,t.id,true);Map<String,Object> data=store.data(r);data.putAll(changes);data.put("hostEpoch",t.hostEpoch);data.put("writerEpoch",t.writerEpoch);data.put("cols",t.cols);data.put("rows",t.rows);data.put("outputSeq",t.outputSeq);r.setState(t.state);if(!ACTIVE.contains(t.state))r.setUniqueKey(null);store.save(PcTable.TERMINAL_SESSION,r,data);return null;});}
    private Map<String,Object> view(Terminal t){Map<String,Object> v=new LinkedHashMap<>();v.put("id",String.valueOf(t.id));v.put("terminalId",String.valueOf(t.id));v.put("sessionId",String.valueOf(t.session));v.put("directoryContextId",String.valueOf(t.workspace));v.put("runnerId",String.valueOf(t.runner));v.put("state",t.state);v.put("reason",t.reason);v.put("hostEpoch",t.hostEpoch);v.put("writerEpoch",t.writerEpoch);v.put("renderer",t.renderer);v.put("cols",t.cols);v.put("rows",t.rows);v.put("outputSeq",t.outputSeq);v.put("inputSeq",t.inputSeq);v.put("createdAt",t.created.toString());return v;}
    private void sendState(Terminal t,Browser b){Map<String,Object> frame=frame(t,"STATE");frame.putAll(view(t));frame.put("clientId",b.identity.clientId);frame.put("inputUncertain",t.inputUncertain);frame.put("canWrite","RUNNING".equals(t.state)&&!t.inputUncertain&&b.identity.clientId.equals(t.writer)&&!b.replaying);sendBrowser(t,b,frame);}
    private void broadcastState(Terminal t){for(Browser b:List.copyOf(t.browsers.values()))sendState(t,b);}
    private void broadcast(Terminal t,Map<String,Object> frame){for(Browser b:List.copyOf(t.browsers.values()))sendBrowser(t,b,frame);}
    private void sendBrowser(Terminal t,Browser b,Map<String,Object> frame){try{authorize(t,b.identity.loginRef,false);send(b.socket,frame);}catch(PcException disconnected){t.browsers.remove(b.socket.getId());close(b.socket);}}
    private Terminal require(long id){enabled();Terminal t=terminals.get(id);if(t==null)throw new PcException(409,"PC_TERMINAL_HOST_LOST","终端进程托管不存在，请核对账本并重新打开");return t;}
    private void sendHost(Terminal t,Map<String,Object> frame){Host host=hosts.get(t.runner);if(host==null||!host.socket.isOpen())throw PcException.conflict("Runner终端连接已断开");devices.authenticate(host.token);send(host.socket,frame);}
    private Map<String,Object> frame(Terminal t,String type){Map<String,Object> f=new LinkedHashMap<>();f.put("type",type);f.put("terminalId",String.valueOf(t.id));f.put("hostEpoch",t.hostEpoch);return f;}
    public void send(WebSocketSession socket,Map<String,Object> frame){outbound.send(socket,frame);}
    public void close(WebSocketSession socket){outbound.closeSession(socket);}
    private static long number(Map<?,?> input,String name,long fallback){Object value=input.get(name);if(value==null)return fallback;try{return Long.parseLong(String.valueOf(value));}catch(Exception e){throw PcException.invalid(name+"必须为整数");}}
    private static int dimension(Map<String,Object> input,String name,int fallback,int min,int max){long n=number(input,name,fallback);if(n<min||n>max)throw PcException.invalid(name+"超出终端允许范围");return (int)n;}
    private static String client(Map<String,Object> input){String c=PcJson.text(input,"clientId");if(!c.matches("[A-Za-z0-9_-]{8,128}"))throw PcException.invalid("窗口clientId无效");return c;}
}
